    layer_kind, layer_cls, weight_key, activation_quant_key, raises
) -> None:
    """Only MXFP4 online methods honor an activation override, `null` included."""
    args = QuantizationConfigArgs(
        **{layer_kind: QuantSpec(weight=weight_key, activation=activation_quant_key)}
    )
    config = OnlineQuantizationConfig(args)
    if raises:
        with pytest.raises(NotImplementedError, match="activation override"):
            config.resolve_quant_method_cls(layer_cls, layer_kind)
        return

    resolved = config.resolve_quant_method_cls(layer_cls, layer_kind)
    assert resolved is not None and resolved[3].activation == activation_quant_key", "helpers": [], "implementation_anchors": ["vllm/model_executor/layers/quantization/online/base.py:315", "vllm/model_executor/layers/quantization/online/base.py:458", "vllm/model_executor/layers/quantization/online/requantization.py:42", "tests/conftest.py:254"], "external_helper_anchors": ["tests/conftest.py:254"], "external_helper_sources": [{"source": "tests/conftest.py:254", "body": "def default_vllm_config():
